// cache-service.ts
// PLY 파일을 IndexedDB에 캐싱하는 서비스

export class CacheService {
    private dbName: string = 'supersplat-cache';
    private storeName: string = 'ply-files';
    private db: IDBDatabase | null = null;
    private dbVersion: number = 1;

    constructor() {
        this.initDB();
    }

    /**
     * IndexedDB 초기화
     */
    private initDB(): Promise<IDBDatabase> {
        return new Promise((resolve, reject) => {
            if (this.db) {
                resolve(this.db);
                return;
            }

            console.log('[CacheService] IndexedDB 초기화 중...');
            const request = indexedDB.open(this.dbName, this.dbVersion);

            request.onupgradeneeded = (event) => {
                console.log('[CacheService] 데이터베이스 업그레이드 중...');
                const db = (event.target as IDBOpenDBRequest).result;
                
                // 기존 스토어가 있으면 삭제
                if (db.objectStoreNames.contains(this.storeName)) {
                    db.deleteObjectStore(this.storeName);
                }
                
                // 스토어 생성
                db.createObjectStore(this.storeName, { keyPath: 'fileName' });
                console.log('[CacheService] 스토어 생성 완료:', this.storeName);
            };

            request.onsuccess = (event) => {
                this.db = (event.target as IDBOpenDBRequest).result;
                console.log('[CacheService] IndexedDB 초기화 성공');
                resolve(this.db);
            };

            request.onerror = (event) => {
                const error = (event.target as IDBOpenDBRequest).error;
                console.error('[CacheService] IndexedDB 초기화 실패:', error);
                reject(error);
            };
        });
    }

    /**
     * 파일을 캐시에 저장
     * @param fileName 파일명
     * @param fileData 파일 데이터
     * @param metadata 추가 메타데이터
     */
    async cacheFile(fileName: string, fileData: ArrayBuffer, metadata: any = {}): Promise<void> {
        try {
            const db = await this.initDB();
            const transaction = db.transaction([this.storeName], 'readwrite');
            const store = transaction.objectStore(this.storeName);

            const cacheData = {
                fileName,
                data: fileData,
                metadata,
                timestamp: Date.now()
            };

            return new Promise((resolve, reject) => {
                const request = store.put(cacheData);
                
                request.onsuccess = () => {
                    console.log(`[CacheService] 파일 캐시 성공: ${fileName} (${Math.round(fileData.byteLength / 1024)} KB)`);
                    resolve();
                };
                
                request.onerror = (error) => {
                    console.error(`[CacheService] 파일 캐시 실패: ${fileName}`, error);
                    reject(error);
                };
            });
        } catch (error) {
            console.error('[CacheService] cacheFile 오류:', error);
            throw error;
        }
    }

    /**
     * 파일을 캐시에서 가져오기
     * @param fileName 파일명
     * @returns 파일 데이터 객체 또는 null (캐시 미스)
     */
    async getCachedFile(fileName: string): Promise<{ data: ArrayBuffer, timestamp: number, metadata: any } | null> {
        try {
            const db = await this.initDB();
            const transaction = db.transaction([this.storeName], 'readonly');
            const store = transaction.objectStore(this.storeName);

            return new Promise((resolve, reject) => {
                const request = store.get(fileName);
                
                request.onsuccess = () => {
                    const result = request.result;
                    if (result) {
                        console.log(`[CacheService] 캐시 적중: ${fileName}`);
                        resolve({
                            data: result.data,
                            timestamp: result.timestamp,
                            metadata: result.metadata
                        });
                    } else {
                        console.log(`[CacheService] 캐시 미스: ${fileName}`);
                        resolve(null);
                    }
                };
                
                request.onerror = (error) => {
                    console.error(`[CacheService] 캐시 조회 실패: ${fileName}`, error);
                    reject(error);
                };
            });
        } catch (error) {
            console.error('[CacheService] getCachedFile 오류:', error);
            return null;
        }
    }

    /**
     * 캐시된 파일 목록 조회
     * @returns 파일명 목록
     */
    async listCachedFiles(): Promise<string[]> {
        try {
            const db = await this.initDB();
            const transaction = db.transaction([this.storeName], 'readonly');
            const store = transaction.objectStore(this.storeName);

            return new Promise((resolve, reject) => {
                const request = store.getAllKeys();
                
                request.onsuccess = () => {
                    const keys = request.result as string[];
                    console.log(`[CacheService] 캐시된 파일 ${keys.length}개 조회 완료`);
                    resolve(keys);
                };
                
                request.onerror = (error) => {
                    console.error('[CacheService] 캐시 목록 조회 실패:', error);
                    reject(error);
                };
            });
        } catch (error) {
            console.error('[CacheService] listCachedFiles 오류:', error);
            return [];
        }
    }

    /**
     * 캐시에서 파일 제거
     * @param fileName 파일명
     */
    async removeCachedFile(fileName: string): Promise<boolean> {
        try {
            const db = await this.initDB();
            const transaction = db.transaction([this.storeName], 'readwrite');
            const store = transaction.objectStore(this.storeName);

            return new Promise((resolve, reject) => {
                const request = store.delete(fileName);
                
                request.onsuccess = () => {
                    console.log(`[CacheService] 캐시 삭제 성공: ${fileName}`);
                    resolve(true);
                };
                
                request.onerror = (error) => {
                    console.error(`[CacheService] 캐시 삭제 실패: ${fileName}`, error);
                    reject(error);
                };
            });
        } catch (error) {
            console.error('[CacheService] removeCachedFile 오류:', error);
            return false;
        }
    }

    /**
     * 특정 기간 이상 지난 캐시 정리
     * @param maxAgeMs 최대 보관 기간 (밀리초)
     */
    async cleanupOldCache(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): Promise<void> {
        try {
            const db = await this.initDB();
            const transaction = db.transaction([this.storeName], 'readwrite');
            const store = transaction.objectStore(this.storeName);
            const now = Date.now();

            // 모든 항목 가져오기
            const request = store.openCursor();
            let deletedCount = 0;

            return new Promise((resolve, reject) => {
                request.onsuccess = (event) => {
                    const cursor = (event.target as IDBRequest).result as IDBCursorWithValue;
                    
                    if (cursor) {
                        const item = cursor.value;
                        // 오래된 캐시 삭제
                        if (now - item.timestamp > maxAgeMs) {
                            cursor.delete();
                            deletedCount++;
                        }
                        cursor.continue();
                    } else {
                        console.log(`[CacheService] 오래된 캐시 ${deletedCount}개 정리 완료`);
                        resolve();
                    }
                };
                
                request.onerror = (error) => {
                    console.error('[CacheService] 캐시 정리 실패:', error);
                    reject(error);
                };
            });
        } catch (error) {
            console.error('[CacheService] cleanupOldCache 오류:', error);
        }
    }
}