// enhanced-s3-loader.ts - 다운로드 진행률 추가 버전
import { Events } from './events';
import { Scene } from './scene';
import { CacheService } from './cache-service';

/**
 * 캐싱과 다운로드 진행률을 지원하는 S3 PLY 파일 로더
 */
export const registerEnhancedS3LoaderEvents = (scene: Scene, events: Events) => {
    // API 엔드포인트 설정
    const API_ENDPOINT = 'https://ymsu2s0hej.execute-api.ap-southeast-2.amazonaws.com/prod/download';
    
    // 캐시 서비스 인스턴스 생성
    const cacheService = new CacheService();
    
    // 캐시 최대 보관 기간 (7일)
    const CACHE_MAX_AGE_MS = 7 * 24 * 60 * 60 * 1000;
    
    // 캐시 정리 실행 (초기화 시)
    cacheService.cleanupOldCache(CACHE_MAX_AGE_MS).catch(err => {
        console.error('[S3 로더] 캐시 정리 중 오류:', err);
    });

    // 로드된 파일명 추적 (세션 내)
    const loadedFiles = new Set<string>();

    // S3 PLY 파일 로드 함수 등록
    events.function('s3.loadPly', async (fileName: string, forceReload: boolean = false) => {
        console.log('[S3 로더] 로드 시작:', fileName, forceReload ? '(강제 리로드)' : '');

        if (!fileName) {
            console.error('[S3 로더] 파일 이름이 제공되지 않았습니다.');
            events.fire('s3.error', '파일 이름이 제공되지 않았습니다.');
            return null;
        }

        try {
            // 파일명 추출 (경로에서 파일명만)
            const extractedFileName = fileName.split('/').pop();
            console.log('[S3 로더] 파일명 추출:', extractedFileName);
            
            // 다운로드 시작을 알림 (기존 스피너 대신 EnhancedSpinner 사용)
            events.fire('s3.downloadStart', extractedFileName);
            
            // 이미 로드된 파일이면 중복 로드 방지 (캐시와 별개로 세션 내에서 중복 로드 방지)
            if (loadedFiles.has(extractedFileName) && !forceReload) {
                console.log('[S3 로더] 이미 로드된 파일입니다. 무시합니다.');
                events.fire('s3.processingComplete');
                return null;
            }
            
            // 먼저 캐시에서 파일을 찾습니다
            if (!forceReload) {
                const cachedFile = await cacheService.getCachedFile(extractedFileName);
                if (cachedFile) {
                    console.log('[S3 로더] 캐시에서 파일을 로드합니다.');
                    events.fire('s3.modelProcessing', '캐시된 파일 로드 중...');
                    
                    // ArrayBuffer를 Blob으로 변환하여 URL 생성
                    const blob = new Blob([cachedFile.data], { type: 'application/octet-stream' });
                    const blobUrl = URL.createObjectURL(blob);
                    
                    console.log('[S3 로더] 캐시된 PLY 파일 로드 중...');
                    
                    try {
                        // 캐시된 데이터로 모델 로드
                        const model = await scene.assetLoader.loadModel({
                            url: blobUrl,
                            filename: extractedFileName
                        });
                        
                        // 리소스 해제
                        URL.revokeObjectURL(blobUrl);
                        
                        // 씬에 모델 추가
                        console.log('[S3 로더] 씬에 모델 추가 (캐시에서 로드)');
                        scene.add(model);
                        
                        // 카메라 포커스 설정
                        scene.camera.focus();
                        
                        // 세션 내 로드 추적
                        loadedFiles.add(extractedFileName);
                        
                        // 처리 완료 알림
                        events.fire('s3.processingComplete');
                        
                        return model;
                    } catch (loadError) {
                        console.error('[S3 로더] 캐시된 데이터 로드 실패:', loadError);
                        console.log('[S3 로더] S3에서 새로 다운로드를 시도합니다.');
                        // 캐시된 데이터 로드 실패 시 새로 다운로드 시도
                        URL.revokeObjectURL(blobUrl);
                    }
                }
            }

            // 캐시 미스 또는 강제 리로드 시 S3에서 다운로드
            console.log('[S3 로더] Presigned URL 생성 중...');
            events.fire('s3.modelProcessing', 'Presigned URL 생성 중...');

            // API를 통해 presigned URL 얻기
            const response = await fetch(`${API_ENDPOINT}?fileName=${encodeURIComponent(fileName)}`);
            console.log('[S3 로더] API 응답 상태:', response.status);

            if (!response.ok) {
                throw new Error(`API 응답 오류: ${response.status} ${response.statusText}`);
            }

            const data = await response.json();
            const presignedUrl = data.body.downloadUrl;

            if (!presignedUrl) {
                throw new Error('유효한 다운로드 URL을 받지 못했습니다.');
            }

            console.log('[S3 로더] Presigned URL 획득 성공:', presignedUrl.substring(0, 50) + '...');

            // 다운로드 시작을 다시 알림 (실제 다운로드 시작)
            console.log('[S3 로더] 다운로드 시작');
            
            // 파일 다운로드 - Fetch API의 progress를 추적하기 위해 XMLHttpRequest 사용
            console.log('[S3 로더] 파일 다운로드 중...');
            
            // XMLHttpRequest로 다운로드 및 진행률 추적
            const fileData = await new Promise<ArrayBuffer>((resolve, reject) => {
                const xhr = new XMLHttpRequest();
                xhr.open('GET', presignedUrl, true);
                xhr.responseType = 'arraybuffer';
                
                // 진행률 이벤트 처리
                xhr.onprogress = (event) => {
                    if (event.lengthComputable) {
                        const progress = event.loaded / event.total;
                        console.log(`[S3 로더] 다운로드 진행률: ${Math.round(progress * 100)}%`);
                        events.fire('s3.downloadProgress', progress);
                    }
                };
                
                xhr.onload = function() {
                    if (this.status >= 200 && this.status < 300) {
                        resolve(xhr.response);
                    } else {
                        reject(new Error(`파일 다운로드 오류: ${xhr.status} ${xhr.statusText}`));
                    }
                };
                
                xhr.onerror = () => {
                    reject(new Error('네트워크 오류로 파일 다운로드에 실패했습니다.'));
                };
                
                xhr.send();
            });

            // 다운로드 완료 알림
            console.log(`[S3 로더] 파일 다운로드 완료 (${Math.round(fileData.byteLength / 1024)} KB)`);
            events.fire('s3.downloadComplete');
            
            // 다운로드한 파일을 캐시에 저장
            console.log('[S3 로더] 파일을 캐시에 저장 중...');
            await cacheService.cacheFile(extractedFileName, fileData, {
                originalUrl: fileName,
                downloadedAt: new Date().toISOString()
            });

            // ArrayBuffer를 Blob으로 변환하여 URL 생성
            const blob = new Blob([fileData], { type: 'application/octet-stream' });
            const blobUrl = URL.createObjectURL(blob);

            console.log('[S3 로더] PLY 파일 로드 중...');
            events.fire('s3.modelProcessing', 'PLY 파일 로드 중...');

            // 모델 로드
            const model = await scene.assetLoader.loadModel({
                url: blobUrl,
                filename: extractedFileName
            });

            // 리소스 해제
            URL.revokeObjectURL(blobUrl);

            console.log('[S3 로더] 모델 로드 완료, 모델 정보:', {
                type: model?.constructor?.name,
                valid: !!model
            });

            // 씬에 모델 추가
            console.log('[S3 로더] 씬에 모델 추가');
            scene.add(model);

            // 카메라 포커스 설정
            console.log('[S3 로더] 카메라 포커스 설정');
            scene.camera.focus();
            
            // 세션 내 로드 추적
            loadedFiles.add(extractedFileName);

            console.log('[S3 로더] 처리 완료 이벤트 발생');
            // 모든 처리 완료 알림
            events.fire('s3.processingComplete');

            return model;
        } catch (error) {
            console.error('[S3 로더] 오류 발생:', error);

            // 강화된 스피너에 오류 전달
            console.log('[S3 로더] 오류 이벤트 발생');
            events.fire('s3.error', error.message || '파일 로드 중 오류가 발생했습니다.');

            // 사용자에게 오류 알림
            await events.invoke('showPopup', {
                type: 'error',
                header: '파일 로드 오류',
                message: `S3에서 파일을 로드하는 중 오류가 발생했습니다: ${error.message}`
            });

            return null;
        } finally {
            // 타임아웃을 통해 처리 완료 이벤트 발생
            console.log('[S3 로더] finally 블록 실행');
            setTimeout(() => {
                console.log('[S3 로더] finally 블록에서 처리 완료 이벤트 발생');
                events.fire('s3.processingComplete');
            }, 1000);
        }
    });

    // URL 파라미터에서 fileName 확인 및 자동 로드
    events.function('s3.checkUrlParams', async () => {
        console.log('[S3 로더] URL 파라미터 확인');
        const url = new URL(window.location.href);
        const fileName = url.searchParams.get('s3File');
        const forceReload = url.searchParams.get('forceReload') === 'true';

        if (fileName) {
            console.log(`[S3 로더] URL 파라미터에서 파일 이름 감지: ${fileName}, 강제 리로드: ${forceReload}`);
            return await events.invoke('s3.loadPly', fileName, forceReload);
        }

        console.log('[S3 로더] URL 파라미터에서 파일 이름 감지되지 않음');
        return null;
    });
    
    // 캐시 관리 기능 추가
    events.function('s3.listCachedFiles', async () => {
        return await cacheService.listCachedFiles();
    });
    
    // 캐시된 파일의 상세 정보 가져오기
    events.function('s3.getCachedFileInfo', async (fileName: string) => {
        try {
            const cachedFile = await cacheService.getCachedFile(fileName);
            if (cachedFile) {
                return {
                    fileName: fileName,
                    size: cachedFile.data.byteLength,
                    timestamp: cachedFile.timestamp,
                    metadata: cachedFile.metadata
                };
            }
            return null;
        } catch (error) {
            console.error(`[S3 로더] 캐시 파일 정보 조회 오류: ${fileName}`, error);
            return null;
        }
    });
    
    events.function('s3.clearCache', async (fileName?: string) => {
        if (fileName) {
            return await cacheService.removeCachedFile(fileName);
        } else {
            const files = await cacheService.listCachedFiles();
            const results = await Promise.all(
                files.map(file => cacheService.removeCachedFile(file))
            );
            return results.every(result => result === true);
        }
    });
};