        //         // 호버 상태 변경 시에만 처리
        //         if (hoveredCamera !== closestCamera) {
        //             // 이전에 호버된 카메라가 있고, 새로 찾은 카메라와 다르면 강조 표시 해제
        //             if (hoveredCamera) {
        //                 console.log(`호버 해제: ${hoveredCamera.id || 'unknown'}`);
        //                 hoveredCamera.highlightModel(false);
        //             }

        //             // 새로 찾은 카메라가 있으면 강조 표시
        //             if (closestCamera) {
        //                 console.log(`호버 활성화: ${closestCamera.id || 'unknown'}`);
        //                 closestCamera.highlightModel(true);
        //                 // 커서 변경 (선택 가능함을 나타냄)
        //                 target.style.cursor = 'pointer';
        //             } else {
        //                 // 카메라가 없으면 기본 커서로 변경
